// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and the amount sent; the crucial deciding value is the amount
    function testFuzz_property(address caller, uint256 amount) public {
        // keep caller as a non-zero address (wide) and amount bounded to a reasonable range
        vm.assume(caller != address(0));
        amount = bound(amount, 0, 20 ether);

        // ensure the caller has funds to send
        vm.deal(caller, amount);

        // warp time forward so require(block.timestamp > pastBlockTime) holds
        // leave pastBlockTime default 0, so any positive timestamp is fine
        vm.warp(block.timestamp + 1);

        bool ok;
        // attempt to call fallback with the fuzzed amount from the fuzzed caller
        vm.prank(caller);
        try c.f{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: when exactly 10 ether is sent, the reference accepts and updates state.
        // We assert that for the chosen inputs, if amount == 10 ether then the call must succeed.
        // The buggy mutant (which requires 9 ether) will fail for amount == 10 ether, so this
        // assertion will fail on the mutant for some fuzzing runs.
        assertTrue(!(amount == 10 ether) || ok);
    }
}

