contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address; the decisive value is the sent amount which we fix to 10 ether via vm.deal
    // but the test must take at least one parameter: use address caller as fuzz parameter
    function testFuzz_property(address caller) public {
        // keep caller admissible (non-zero) but wide
        vm.assume(caller != address(0));

        // arrange: fund the caller so it can send 10 ether
        uint256 amount = 10 ether;
        vm.deal(caller, amount);

        // set a known later timestamp to ensure block.timestamp > pastBlockTime if needed
        // ensure pastBlockTime is less than current timestamp by warping back then forward
        // first warp to a past time and call once to set pastBlockTime low
        vm.warp(1);
        vm.prank(caller);
        // send exact amount so the reference will accept; mutant requiring 9 ether will revert here for amount==10 ether
        (bool okFirst, ) = address(c).call{value: amount}("");
        // okFirst may be true or false depending on contract variant; we don't assert here

        // now advance time to ensure block.timestamp > pastBlockTime (if previous call set it)
        vm.warp(block.timestamp + 100);

        // perform the decisive call: send exactly 10 ether from the fuzzed caller
        vm.prank(caller);
        bool ok;
        try c.f{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: for the reference contract, calling fallback with exactly 10 ether does not revert
        // and therefore ok must be true for all admissible inputs. The mutant that expects 9 ether will revert on 10 ether
        // so ok will be false for some inputs (here amount == 10 ether), distinguishing the mutant.
        assertTrue(ok);
    }
}

