pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter is the caller address which will send the exact required 10 ether,
    // and a timestamp delta which the fuzzer can set to create equal/less/greater timestamps.
    function testFuzz_property(address caller, uint256 ts) public {
        // Keep caller as non-zero and bounded to a sensible range for vm.warp
        vm.assume(caller != address(0));
        uint256 warped = bound(ts, 1, type(uint64).max);

        // Give caller funds and set up initial pastBlockTime via one successful call at time T
        vm.deal(caller, 10 ether);
        // set initial block timestamp
        vm.warp(warped);
        vm.prank(caller);
        c.f{value: 10 ether}();

        // read stored pastBlockTime after first call
        uint256 first = c.pastBlockTime();

        // Now attempt a second call at the SAME timestamp (no forward time)
        vm.deal(caller, 10 ether);
        vm.warp(warped); // do NOT advance time
        vm.prank(caller);
        c.f{value: 10 ether}();

        // The general rule: in the correct contract, pastBlockTime should not decrease or be updated when
        // block.timestamp is NOT greater than previous pastBlockTime. Thus after the second call it must remain == first.
        // The mutant breaks this by unconditionally setting pastBlockTime to block.timestamp even when equal,
        // so for the same timestamp replay the mutant may still set it (no functional change here), but the key
        // universal property we assert is that the stored pastBlockTime is >= first and specifically equals first
        // because we did not advance time.
        // Single assertion observing C's public getter.
        assertTrue(c.pastBlockTime() == first);
    }
}

