        vm.warp(t0);
        vm.prank(caller);
        c.call{value: 10 ether}("");

        // Record pastBlockTime after first call
        uint256 first = c.pastBlockTime();

        // Second call at time t1 with exactly 10 ether
        vm.warp(t1);
        vm.prank(caller);
        c.call{value: 10 ether}("");

