pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor address and a timestamp and a second timestamp equal/possibly equal
    function testFuzz_property(address actor, uint64 t1, uint64 t2) public {
        // keep actor non-zero
        vm.assume(actor != address(0));

        // bound timestamps to reasonable block timestamp range
        uint256 ts1 = bound(uint256(t1), 1, type(uint32).max);
        uint256 ts2 = bound(uint256(t2), 1, type(uint32).max);

        // ensure both calls send the required 10 ether
        uint256 sendAmt = 10 ether;
        vm.deal(actor, sendAmt * 2);

        // First call at ts1
        vm.warp(ts1);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: sendAmt}("");
        require(ok1, "first call should succeed");
        uint256 after1 = c.pastBlockTime();

        // Second call at ts2
        vm.warp(ts2);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: sendAmt}("");
        require(ok2, "second call should succeed");
        uint256 after2 = c.pastBlockTime();

        // General rule (one assertion): If second call's timestamp is NOT greater than the stored pastBlockTime after first call,
        // then the reference contract must NOT update pastBlockTime on the second call. That is, when ts2 <= after1, after2 == after1.
        // The mutant which unconditionally updates pastBlockTime would make after2 == ts2 even when ts2 <= after1.
        if (ts2 <= after1) {
            assertTrue(after2 == after1);
        } else {
            // when ts2 > after1, both should update to ts2; assert that after2 == ts2
            assertTrue(after2 == ts2);
        }
    }
}

