pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed: actor is the caller; doSecondSameTimestamp decides whether the second call is in the same timestamp
    function testFuzz_property(address actor, bool doSecondSameTimestamp) public {
        // keep actor non-zero and distinct from this contract
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // fund the actor so it can send 10 ether twice
        vm.deal(actor, 20 ether);

        // First call: send exactly 10 ether; must succeed on both reference and mutant
        vm.prank(actor);
        c.f{value: 10 ether}();

        // capture stored pastBlockTime after first call
        uint256 firstStored = c.pastBlockTime();

        // Decide whether the second call happens at same timestamp or after
        if (!doSecondSameTimestamp) {
            // advance time strictly to ensure timestamp > firstStored
            // choose warp to firstStored + 1 if firstStored > block.timestamp, else current +1
            uint256 target = firstStored >= block.timestamp ? firstStored + 1 : block.timestamp + 1;
            vm.warp(target);
        } else {
            // keep same timestamp: warp to exactly the timestamp that produced firstStored
            // Note: firstStored may be 0 if first call reverted — but first call should not revert because msg.value==10 ether
            vm.warp(firstStored);
        }

        // Second call: send exactly 10 ether again
        vm.prank(actor);
        c.f{value: 10 ether}();

        // After the second call, the reference guarantees: if timestamp did NOT increase, pastBlockTime remains equal to firstStored.
        // The mutant (which unconditionally updates pastBlockTime) will set pastBlockTime to the (same) timestamp even when reference would not.
        // We assert the property that for the chosen domain the reference must satisfy: when doSecondSameTimestamp==true, pastBlockTime == firstStored.
        if (doSecondSameTimestamp) {
            assertTrue(c.pastBlockTime() == firstStored);
        } else {
            // when we advanced time, both reference and mutant will set pastBlockTime to the new timestamp; assert it changed (> firstStored)
            assertTrue(c.pastBlockTime() > firstStored);
        }
    }
}

