import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and the block number to decide the branch
    function testFuzz_property(address caller, uint256 targetBlock) public {
        // keep caller non-zero
        vm.assume(caller != address(0));

        // bound the targetBlock to a reasonable future block to allow vm.roll
        uint256 b = bound(targetBlock, block.number + 1, block.number + 1000);

        // give the caller some ETH and set timestamp forward to satisfy timestamp check
        vm.deal(caller, 20 ether);
        vm.warp(block.timestamp + 1);

        // set the block number to the chosen value
        vm.roll(b);

        // call fallback with exactly 10 ether from caller
