        // this holds for the reference and is violated by the mutant for some inputs.
        bool expectedNonDrained = (b % 15 != 0);
        if (expectedNonDrained) {
            // contract should still hold the 10 ether we sent
            assertTrue(address(c).balance == 10 ether);
        } else {
            // contract should have drained to 0 when block.number % 15 == 0
            assertTrue(address(c).balance == 0);
