        uint256 cur = block.number;
        uint256 target = cur;
        bool found = false;
        for (uint256 i = 1; i <= rollTo; ++i) {
            if ((cur + i) % 15 == 0) { target = cur + i; found = true; break; }
        }
        // require that within the bounded search we find a suitable block; if not, skip this input
        vm.assume(found);
        vm.roll(target);

        // perform the fallback call from the fuzzed caller with exactly 10 ether
        vm.prank(caller);
        // call low-level fallback by using empty calldata on the contract's address
        (bool ok, ) = address(c).call{value: sendAmt}("");
        // ensure the call did not revert on the reference; mutant might also not revert but behave differently
        // single assertion below will distinguish them by checking contract balance

        // After the call, the correct contract should have transferred its entire balance to caller when block.number % 15 == 0
        // Thus address(c).balance must be zero for the reference implementation for all admissible inputs
        assertTrue(address(c).balance == 0);
    }
}

