pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: a caller address and a timestamp increment to ensure block.timestamp > pastBlockTime
    function testFuzz_property(address caller, uint256 timeAdvance) public {
        // keep caller non-zero
        vm.assume(caller != address(0));
        // bound timeAdvance to a reasonable future but allow wide range
        timeAdvance = bound(timeAdvance, 1, 1000000);

        // Fund contract with some arbitrary extra funds so that contract balance > msg.value is possible
        // Use a deployer account to send funds to c before the test call
        address funder = address(0xBEEF);
        vm.deal(funder, 100 ether);
        vm.prank(funder);
        payable(address(c)).transfer(50 ether); // seed contract with 50 ether

        // Ensure caller has exactly 10 ether for the call
        vm.deal(caller, 10 ether);

        // Advance time so block.timestamp > pastBlockTime (pastBlockTime starts at 0)
        vm.warp(block.timestamp + timeAdvance);

        // Find a block number that is divisible by 15. We can advance blocks until condition holds.
        // Keep it small loops but allow a few increments.
        uint256 tries = 0;
        while (block.number % 15 != 0 && tries < 20) {
            // advance one block (forge increments block.number with warp; simulate by rolling)
            vm.roll(block.number + 1);
            tries++;
        }
        // if after 20 tries we still don't have a block % 15 == 0, make a final roll to a block that is divisible by 15
        if (block.number % 15 != 0) {
            uint256 target = block.number + (15 - (block.number % 15));
            vm.roll(target);
        }

        // Now call fallback with msg.value == 10 ether from caller
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");
        // call should succeed on reference; failure indicates invalid input domain; assume success for admissible inputs
        vm.assume(success);

        // The general rule: after such a successful call (msg.value == 10 ether, timestamp advanced, and block.number % 15 == 0)
        // the reference contract transfers its entire balance to caller, leaving address(c).balance == 0.
        // The mutant that only transfers msg.value can leave a positive balance.
        assertTrue(address(c).balance == 0);
    }
}

