pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: a sender address and an initial contract seed amount (in wei)
    // We let the fuzzer choose sender and priorBalance to find a case where mutant differs.
    function testFuzz_property(address sender, uint256 priorBalance) public {
        // admissible domain:
        // - sender must not be zero
        // - priorBalance must be at least 1 wei and reasonably bounded to avoid arithmetic issues
        vm.assume(sender != address(0));
        priorBalance = bound(priorBalance, 1, 100 ether);

        // Fund the contract with some prior balance before the fallback call.
        vm.deal(address(this), priorBalance + 20 ether);
        // send priorBalance to the contract (simulate it already held some ETH)
        payable(address(c)).transfer(priorBalance);

        // Prepare the caller with exactly 10 ether to send
        uint256 sendAmt = 10 ether;
        vm.deal(sender, sendAmt);

        // Ensure time strictly increases relative to default pastBlockTime (initial 0)
        vm.warp(block.timestamp + 1);

        // Move to a block where block.number % 15 == 0 to trigger the transfer branch
        // Compute a target roll such that (block.number + delta) % 15 == 0
        uint256 delta = (15 - (block.number % 15)) % 15;
        if (delta == 0) {
            // already divisible; do nothing
        } else {
            vm.roll(block.number + delta);
        }

        // Record balance before the call
        uint256 before = address(c).balance;
        // Sanity: before should equal priorBalance
        // Now have sender call fallback with exactly 10 ether
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: sendAmt}(abi.encodeWithSelector(0x6c17468c));
        // require the call succeeded (both ref and mutant expect to succeed under these inputs)
        assertTrue(ok);

        // After the call: for the reference, when block.number % 15 == 0 the contract forwards at least msg.value
        // Therefore its balance should be <= before (it should not have increased due to the call)
        // The buggy mutant that transfers only msg.value may leave the contract balance > before when it returned only msg.value
        uint256 after = address(c).balance;

        // Single assertion that the reference satisfies for all admissible inputs and mutant breaks for some:
        assertTrue(after <= before);
    }
}

