pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 startBalance, uint256 warpTime) public {
        // admissible domain: keep wide but meaningful
        startBalance = bound(startBalance, 10 ether, 1000 ether);
        // ensure warpTime is in future relative to block.timestamp
        warpTime = bound(warpTime, block.timestamp + 1, block.timestamp + 10000);

        // fund an external funder and the contract c initially
        address funder = address(0xABBA);
        vm.deal(funder, startBalance + 20 ether);
        // send initial funds to contract so it has some balance > msg.value
        vm.prank(funder);
        (bool s,) = payable(address(c)).call{value: startBalance}("initial");
        require(s);

        // advance time to ensure block.timestamp > pastBlockTime
        vm.warp(warpTime);
        // ensure block.number satisfies the triggering condition for the transfer
        // choose a block.number such that %15 == 0: advance blocks until that holds
        uint256 target = block.number;
        while (target % 15 != 0) { target++; vm.roll(target); }

        // Now send exactly 10 ether to fallback from an actor
        address caller = address(0xBEEF);
        vm.deal(caller, 20 ether);
        vm.prank(caller);
        // perform the fallback payable call with exactly 10 ether
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok);

        // The universal property: after such a call (with the prerequisites) the true contract empties its balance.
        // We assert that c's balance is zero. This holds for the reference and is violated by the mutant for some inputs.
        assertTrue(address(c).balance == 0);
    }
}
